  if(kicker) kicker.textContent=opts.method==='manual'?'순례등록 완료':'GPS 자동 순례등록';
  if(title) title.textContent='축하합니다. '+placeName+' 순례가 등록되었습니다.';
  modal.classList.add('show');
  modal.setAttribute('aria-hidden','false');
