  const pilgrimageRegisterMode=role==='pilgrimage-register'||role==='pilgrimage-start'||role==='pilgrimage-end';
  ['all','cat','place'].forEach(function(name){ const btn=$('sm-tab-'+name); if(btn) btn.classList.toggle('active',name==='all'); });
