  function openCourse(id){
    pilgrimageManualCreateMode=false;pilgrimageManualDraftCourse=null;
    const c=loadCourses().find(x=>x.id===id);if(!c)return;
    const active=_activeFollowState();
    const isCurrentActive=!!(active&&active.courseId===String(id||''));
    // 진행 중인 코스는 어느 탭에서 열더라도 '과거 완료기록'보다
    // 이번 순례의 현재 진행상태를 우선해서 보여준다.
    pilgrimageDetailMode=isCurrentActive?'plan':(pilgrimageCourseTab==='complete'?'complete':'plan');
    applyCourse(isCurrentActive?active.course:c);
    setView('detail');
    renderDetail();
  }
  function repeatCourse(id,confirmed){
    const targetId=String(id||'');
    const active=_activeFollowState();
    if(active&&active.courseId===targetId){stopActiveFollow(targetId);return;}
    if(active&&active.courseId&&active.courseId!==targetId){openFollowSwitchConfirm(targetId,'repeat');return;}
    if(!confirmed){openFollowStartConfirm(targetId,'repeat');return;}
    let a=loadCourses(),i=a.findIndex(x=>String(x.id)===targetId);if(i<0)return;
    const original=JSON.parse(JSON.stringify(a[i]));
    _writeRepeatEditGuard(original);
    const now=Date.now(),c=Object.assign({},a[i]);
    c.places=(Array.isArray(c.places)?c.places:[]).map(x=>Object.assign({},x,{done:false,doneMethod:''}));
    c.lastStartedAt=now;c.updatedAt=now;c.completionArmed=true;a[i]=c;saveCourses(a);
    pilgrimageDetailMode='plan';
    applyCourse(c);
    try{localStorage.setItem(ACTIVE_FOLLOW_KEY,JSON.stringify({courseId:c.id,startedAt:now}));}catch(_e){}
    _recordDailyFollowSession(c,now);
    try{renderCourseList();}catch(_e){}
    // 완료 목록의 '다시 순례하기'에서 시작했다면
    // 버튼만 '순례 종료'로 바꾸고 목록에 머무르지 말고
    // 해당 코스의 현재 순례하기 상세 화면으로 바로 이동한다.
    if(plannerView==='list'){
      setView('detail');
      renderDetail();
      return;
    }
    if(plannerView==='detail'){
      setView('detail');
      renderDetail();
    }
  }
