  function confirmSave(){const input=document.getElementById('oai-pilgrimage-save-name'),name=String(input&&input.value||'').trim();if(!name){input&&input.focus();return;}const renameCourseId=input&&input.dataset.renameCourseId;if(renameCourseId){const a=loadCourses(),i=a.findIndex(c=>c.id===renameCourseId);if(i>=0){a[i]=Object.assign({},a[i],{name,updatedAt:Date.now()});saveCourses(a);if(currentCourseId===renameCourseId){const meta=loadMeta();meta.name=name;saveMeta(meta,true);}}closeSaveModal();renderCourseList();return;}const meta=loadMeta();meta.name=name;saveMeta(meta,true);if(pilgrimageManualCreateMode){
      const dateInput=document.getElementById('oai-pilgrimage-manual-date');
      const completedAt=dateInput?_courseDateValueToTs(dateInput.value):0;
      if(!completedAt){
        closeSaveModal();
        alert('다녀온 날짜를 선택해 주세요.');
        try{if(dateInput)dateInput.focus();}catch(_e){}
        return;
      }
      const d=draftSnapshot(),now=Date.now();
      if(!normalizePoint(d.end)){
        closeSaveModal();
        alert('순례완료로 저장하려면 도착지를 먼저 등록해 주세요.');
        return;
      }
      d.places=(Array.isArray(d.places)?d.places:[]).map(function(p){
        return Object.assign({},p,{done:true,doneMethod:'manual'});
      });
      const manualCourse=Object.assign({
        id:'course_'+now+'_'+Math.random().toString(36).slice(2,7),
        name:name,
        updatedAt:now,
        lastStartedAt:0,
        completionArmed:false,
        completions:[{
          completedAt:completedAt,
          placeCount:d.places.length,
          method:'manual',
          locked:false
        }],
        lastCompletedAt:completedAt
      },d,{name:name});
      _courseRefreshCompletionState(manualCourse);
      if(!_courseCompletionList(manualCourse).length){
        closeSaveModal();
        alert('순례완료 기록을 만들지 못했습니다. 출발지·도착지와 날짜를 확인해 주세요.');
        return;
      }
      const courses=loadCourses();
      courses.unshift(manualCourse);
      saveCourses(courses);
      closeSaveModal();
      pilgrimageManualCreateMode=false;
      pilgrimageManualDraftCourse=null;
      currentCourseId='';
      clearDraft();
      if(dateInput)dateInput.value='';
      pilgrimageCourseTab='complete';
      pilgrimageCourseFilterState.year='all';
      pilgrimageCourseFilterState.month='all';
      pilgrimageCourseFilterState.sort='completed';
      setView('list');
      renderCourseList();
      return;
    }if(input&&input.dataset.renameOnly==='1'){if(currentCourseId)updateCurrentCourseProgress();closeSaveModal();renderDetail();return;}const d=draftSnapshot();let a=loadCourses();if(currentCourseId){const i=a.findIndex(c=>c.id===currentCourseId);if(i>=0)a[i]=Object.assign({},a[i],d,{updatedAt:Date.now()});else currentCourseId='';}if(!currentCourseId){currentCourseId='course_'+Date.now()+'_'+Math.random().toString(36).slice(2,7);a.unshift(Object.assign({id:currentCourseId,updatedAt:Date.now(),lastStartedAt:Date.now(),completionArmed:true,completions:[]},d));}saveCourses(a);closeSaveModal();renderDetail();flashSaved();const next=pendingAfterSave;pendingAfterSave='';if(next==='follow')setTimeout(()=>openFollow(),120);}
  function saveCurrent(){
    const list=loadPlan(),meta=loadMeta();
    if(!list.length&&!pilgrimageManualCreateMode&&!(normalizePoint(meta.start)&&normalizePoint(meta.end))){
      alert('순례 장소를 추가하거나 출발지와 도착지를 모두 설정해 주세요.');
      return;
    }
    if(!list.length&&pilgrimageManualCreateMode){
      alert('다녀온 성지·성당을 먼저 등록해 주세요.');
      return;
    }
    if(pilgrimageManualCreateMode){
      const meta=loadMeta();
      if(!normalizePoint(meta.end)){
        alert('순례완료로 저장하려면 도착지를 먼저 등록해 주세요.');
        return;
      }
      const dateInput=document.getElementById('oai-pilgrimage-manual-date');
      const completedAt=dateInput?_courseDateValueToTs(dateInput.value):0;
      if(!completedAt){
        alert('다녀온 날짜를 선택해 주세요.');
        try{if(dateInput)dateInput.focus();}catch(_e){}
        return;
      }
      pendingAfterSave='';
      openSaveModal(false);
      return;
    }
    if(!_pilgrimageDraftIsDirty())return;
    pendingAfterSave='';
    if(!currentCourseId){openSaveModal(false);return;}
    if(_saveActiveEditedDraftAsNewCourse())return;
    updateCurrentCourseProgress();
    renderDetail();
    flashSaved();
  }

  function _pilgrimageFindRegisteredEndpoint(point){
    const q=normalizePoint(point);if(!q)return null;
    const qn=_normPilgrimageName(q.name);
    let hit=null;
    try{
      if(Array.isArray(SHRINES)){
        let best=null,bestD=Infinity;
        SHRINES.forEach(function(s){if(!s||!_validGpsPair(s.lat,s.lng))return;const same=qn&&_normPilgrimageName(s.name)===qn;const d=calcDist(q.lat,q.lng,Number(s.lat),Number(s.lng));if((same||d<=0.20)&&d<bestD){best=s;bestD=d;}});
        if(best)hit={type:'shrine',item:best,radius:(Number(best.gpsRadiusM)>0?Number(best.gpsRadiusM):OAI_SHRINE_AUTO_VISIT_RADIUS_M)};
      }
    }catch(_e){}
    if(hit)return hit;
    try{
      if(Array.isArray(PARISHES)){
        let best=null,bestD=Infinity;
        PARISHES.forEach(function(s){if(!s||s.diocese==='군종교구'||!_validGpsPair(s.lat,s.lng))return;const same=qn&&_normPilgrimageName(s.name)===qn;const d=calcDist(q.lat,q.lng,Number(s.lat),Number(s.lng));if((same||d<=0.15)&&d<bestD){best=s;bestD=d;}});
        if(best)hit={type:'parish',item:best,radius:OAI_PARISH_AUTO_VISIT_RADIUS_M};
      }
    }catch(_e){}
    return hit;
  }

  function _pilgrimageRegisteredDestination(point){
    try{
      const hit=_pilgrimageFindRegisteredEndpoint(point);
      if(!hit||!hit.item)return null;
      if(hit.type==='parish'&&hit.item.diocese==='군종교구')return null;
      return hit;
    }catch(_e){return null;}
  }
  function _pilgrimageDestinationCanFollow(point){
    return !!_pilgrimageRegisteredDestination(point);
  }
  window._oaiPilgrimageEndpointGpsCheck=function(lat,lng,opts){
    opts=opts||{};
    if(!Number.isFinite(Number(lat))||!Number.isFinite(Number(lng)))return {registered:0,names:[]};
    const meta=loadMeta(),date=_todayISODate(),seen={},names=[];
    [meta.start,meta.end].forEach(function(point){
      const hit=_pilgrimageFindRegisteredEndpoint(point);if(!hit||!hit.item)return;
      // 출발/도착 지점이 '내 본당'이면 순례용 GPS 방문등록에서 제외한다.
      // 대부분 내 본당에서 모여 출발하거나 해산하므로 코스 순례기록에 자동 방문으로 남기지 않는다.
      if(hit.type==='parish'){
        try{const myParish=_configuredMyParish();if(myParish&&_isSameParish(hit.item,myParish))return;}catch(_e){}
      }
      const key=hit.type+'|'+String(hit.item.diocese||'')+'|'+String(hit.item.name||'');if(seen[key])return;seen[key]=1;
      let meters=Infinity;
      if(hit.type==='shrine'&&Array.isArray(hit.item.gpsPoints)&&hit.item.gpsPoints.length){
        hit.item.gpsPoints.forEach(function(gp){if(gp&&_validGpsPair(gp.lat,gp.lng)){const m=calcDist(Number(lat),Number(lng),Number(gp.lat),Number(gp.lng))*1000;if(m<meters)meters=m;}});
      }
      if(!Number.isFinite(meters)&&_validGpsPair(hit.item.lat,hit.item.lng))meters=calcDist(Number(lat),Number(lng),Number(hit.item.lat),Number(hit.item.lng))*1000;
      if(meters>Number(hit.radius||150))return;
      const visitResult=_registerGpsPlaceVisit(hit.type,hit.item,date);
      if(visitResult.added)names.push(String(hit.item.name||''));
    });
    if(names.length){
      try{_refreshShrineVisitMapState();}catch(_e){}
      try{_updateParishVisitButton();}catch(_e){}
    }
    if(!opts.silent){
      const note=document.getElementById('oai-pilgrimage-current-check-note');
      if(note)note.textContent=names.length?('GPS 등록 완료: '+names.join(', ')):('현재 위치 확인 완료 · 출발/도착 GPS 등록 대상이 없거나 이미 오늘 등록되었습니다. 내 본당은 제외됩니다.');
    }
    return {registered:names.length,names:names};
  };
  function checkPilgrimageCurrentLocation(){
    const btn=document.querySelector('[data-oai-pilgrimage-current-check]'),note=document.getElementById('oai-pilgrimage-current-check-note');
    if(btn){btn.classList.add('is-checking');btn.disabled=true;}
    if(note)note.textContent='현재 위치를 확인하고 있습니다…';
    const done=function(lat,lng){
      try{_setMyLoc(Number(lat),Number(lng),{suppressAutoShrineVisit:true});}catch(_e){}
      const r=_oaiHandleGpsArrival(Number(lat),Number(lng),{endpointNow:true,endpointSilent:false,skipEndpoint:true});
      try{_savePilgrimageLivePosition(Number(lat),Number(lng));}catch(_e){}
      try{calcDetailItemMetrics({lat:Number(lat),lng:Number(lng)},{remainingOnly:!!_activeFollowState()});}catch(_e){}
      try{calcPilgrimageTotalRoute({lat:Number(lat),lng:Number(lng)},{remainingOnly:!!_activeFollowState()});}catch(_e){}
      if(btn){btn.classList.remove('is-checking');btn.disabled=false;}
      if(note&&!r.registered)note.textContent='현재 위치 확인 완료 · 순례지 GPS 등록과 출발·도착 성지/성당 등록을 확인했습니다. 내 본당은 제외됩니다.';
    };
    const fail=function(){if(btn){btn.classList.remove('is-checking');btn.disabled=false;}if(note)note.textContent='현재 위치를 확인하지 못했습니다. 위치 권한과 GPS를 확인해 주세요.';};
    try{
      if(typeof _refreshFreshLocationThen==='function')_refreshFreshLocationThen(done,fail);
      else if(typeof currentPosition==='function')currentPosition(done,fail);
      else fail();
    }catch(_e){fail();}
  }
  function pointModal(){return document.getElementById('oai-pilgrimage-point-modal');}
